-- Reconstructed LC Pro Full Stack launch migration from the verified production state.
-- The remote version 20260901122940 already exists. Modules 8–10, projects and final
-- assessment were seeded in the same implementation session before the launch gate ran.

with payload as (
 select * from jsonb_to_recordset($modules$[{"title":"Testes e Qualidade","position":8,"description":"Testes, depuração, observabilidade, revisão de código e critérios de aceite."},{"title":"Deploy e Produção","position":9,"description":"Variáveis de ambiente, CI/CD, domínio, logs, rollback e operação segura."},{"title":"Portfólio e Projeto Final","position":10,"description":"Projeto Full Stack integrador, documentação, README, apresentação e publicação no portfólio."}]$modules$::jsonb)
 as x(position int,title text,description text)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
update nexora.modules m
set title=p.title,description=p.description
from payload p,c
where m.course_id=c.id and m.position=p.position;

with payload as (
 select * from jsonb_to_recordset($lessons$[{"title":"Estratégia de testes e pirâmide de confiança","content":[{"body":"Um sistema pode ter milhares de testes e ainda falhar no fluxo que gera receita. Quantidade não é estratégia: cada tipo de teste precisa responder a um risco concreto.","type":"story","title":"Cenário"},{"body":"Testes unitários validam regras isoladas; integração valida colaboração entre partes; contrato valida acordos entre serviços; E2E valida jornadas críticas. O conjunto deve maximizar confiança sem tornar o feedback lento.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Teste a regra no nível mais barato que ainda detecta o defeito.","Reserve E2E para fluxos de maior valor e risco.","Evite duplicar a mesma verificação em todas as camadas.","Meça flakiness e tempo de execução como dívida de qualidade."],"title":"Como aplicar"},{"body":"Uma regra de desconto deve ter testes unitários de fronteira; a persistência pode ter integração com banco; o checkout crítico merece ao menos um E2E. Cada teste protege uma camada diferente.","type":"example","title":"Exemplo profissional"},{"body":"Cobrir apenas o caminho feliz cria falsa sensação de segurança. Fronteiras, vazio, erro e autorização costumam produzir defeitos mais caros.","type":"mistake","title":"Erro comum"},{"body":"Classifique cinco riscos de um checkout em unitário, integração, contrato ou E2E e justifique o nível escolhido.","type":"guided_practice","title":"Prática orientada"},{"body":"Em produto real, a suíte é um sistema de feedback. Se demora demais ou falha aleatoriamente, a equipe começa a ignorá-la.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Tipos de teste protegem riscos diferentes.","E2E não substitui testes menores.","Velocidade e confiabilidade da suíte importam.","Risco determina profundidade de teste."]}],"lab_type":"checkpoint","position":1,"objective":"Definir uma estratégia de testes proporcional ao risco, separando testes unitários, integração, contrato e ponta a ponta.","xp_reward":150,"difficulty":3,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Testar tudo apenas com E2E.","Usar o nível de teste mais barato que detecta o risco e reservar E2E para jornadas críticas.","Evitar testes de integração.","Medir qualidade apenas por quantidade de testes."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual decisão representa melhor uma estratégia de testes saudável?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":8,"estimated_minutes":33},{"title":"Testes unitários com casos de fronteira","content":[{"body":"Muitos bugs vivem exatamente no valor-limite: 18 anos, estoque zero, desconto em R$ 300, paginação no último item. Um teste que cobre apenas números confortáveis pode passar sem provar a regra.","type":"story","title":"Cenário"},{"body":"Um teste unitário útil possui preparação mínima, ação clara e asserção sobre comportamento observável. Casos de fronteira são derivados da própria regra, não escolhidos ao acaso.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Teste abaixo, no limite e acima quando houver comparação.","Inclua entradas inválidas e ausência de dados.","Evite testar detalhes internos que podem mudar sem alterar comportamento.","Dê nomes que expressem regra e resultado."],"title":"Como aplicar"},{"body":"Para frete grátis a partir de R$ 200, os casos 199,99 → 20; 200 → 0; 350 → 0 protegem a fronteira real.","type":"example","title":"Exemplo profissional"},{"body":"Testar apenas a implementação atual torna refactor perigoso: qualquer reorganização quebra testes mesmo quando o comportamento permanece correto.","type":"mistake","title":"Erro comum"},{"body":"Crie casos para uma regra de senha com mínimo de 10 caracteres e bloqueio de senha vazia. Inclua valores imediatamente ao redor do limite.","type":"guided_practice","title":"Prática orientada"},{"body":"Bons testes funcionam como documentação executável. Quem lê entende a regra antes de abrir a implementação.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Fronteiras derivam da regra.","Teste comportamento, não estrutura interna.","Erro e ausência fazem parte do contrato.","Nome do teste deve comunicar intenção."]}],"lab_type":"checkpoint","position":2,"objective":"Escrever testes unitários que validem comportamento, incluindo limites, erro e invariantes.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["1, 2 e 3","17, 18 e 19","18, 28 e 38","0, 50 e 100"],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual trio valida melhor uma regra 'idade mínima de 18 anos'?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":8,"estimated_minutes":36},{"title":"Testes de integração com banco e APIs","content":[{"body":"Mocks podem dizer que uma query funciona enquanto a constraint real rejeita o dado. Integração existe para verificar a costura entre componentes que, isoladamente, parecem corretos.","type":"story","title":"Cenário"},{"body":"Teste de integração executa partes reais da infraestrutura em ambiente controlado. O foco é contrato: schema, transação, serialização, código HTTP, autorização e efeitos persistidos.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Prepare dados isolados por teste.","Limpe ou recrie estado de forma determinística.","Teste constraints e transações reais.","Não use produção como ambiente de teste."],"title":"Como aplicar"},{"body":"Ao criar usuário, o teste envia request à API de teste, confirma 201 e verifica no banco que senha não foi persistida em texto claro e e-mail único foi respeitado.","type":"example","title":"Exemplo profissional"},{"body":"Mockar o banco em todos os testes elimina justamente o risco de integração que mais precisa ser verificado.","type":"mistake","title":"Erro comum"},{"body":"Desenhe um teste de integração para criação de pedido com itens, estoque e transação. Defina o que deve acontecer quando uma etapa falha.","type":"guided_practice","title":"Prática orientada"},{"body":"Integração bem testada reduz incidentes de migrations, contratos quebrados e diferenças entre ambientes.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Integração valida colaboração real.","Estado de teste precisa ser isolado.","Banco e contrato real devem participar quando são o risco.","Produção nunca é laboratório."]}],"lab_type":"checkpoint","position":3,"objective":"Validar contratos reais entre aplicação, banco e serviços sem confundir integração com teste unitário.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Quando queremos testar CSS.","Quando o risco está em constraints, transações ou SQL real.","Quando não existe regra de persistência.","Quando queremos evitar qualquer infraestrutura."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Quando um teste com banco real de teste é mais valioso que um mock?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":8,"estimated_minutes":39},{"title":"Depuração baseada em evidência","content":[{"body":"Alterar código até o bug desaparecer pode esconder a causa e criar outro defeito. Depuração profissional transforma sintomas em evidências reproduzíveis.","type":"story","title":"Cenário"},{"body":"O ciclo é: reproduzir, delimitar, formular hipótese, coletar evidência, testar a hipótese, corrigir e criar prevenção. Logs e traces servem para responder perguntas específicas, não para despejar dados.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Registre entrada e resultado sem expor segredos.","Compare um caso que funciona com um que falha.","Reduza o problema até a menor reprodução.","Depois da correção, adicione teste que falharia antes."],"title":"Como aplicar"},{"body":"Se um pedido falha apenas com cupom, compare payloads, isole a validação do cupom e confirme se o erro nasce antes ou depois da persistência.","type":"example","title":"Exemplo profissional"},{"body":"Adicionar logs com token, senha ou payload completo de dados pessoais aumenta risco de segurança enquanto tenta resolver outro problema.","type":"mistake","title":"Erro comum"},{"body":"Monte um roteiro de depuração para um erro 500 que só ocorre quando há dois itens iguais no carrinho.","type":"guided_practice","title":"Prática orientada"},{"body":"Incidente bem investigado deixa uma melhoria permanente: teste, alerta, validação ou documentação.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Reprodução vem antes da correção.","Hipóteses precisam de evidência.","Logs devem ser mínimos e seguros.","Correção deve ganhar teste de regressão."]}],"lab_type":"checkpoint","position":4,"objective":"Investigar falhas com reprodução, hipótese, observabilidade e redução sistemática do problema.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Mudar várias partes do código.","Delimitar onde a falha começa e formular uma hipótese testável.","Excluir os logs.","Fazer deploy direto de uma tentativa."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual é o melhor passo logo após reproduzir um bug de forma consistente?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":8,"estimated_minutes":30},{"title":"Code review e critérios de merge","content":[{"body":"Code review não é caça a estilo pessoal. O objetivo é reduzir risco antes que uma mudança se torne parte do sistema compartilhado.","type":"story","title":"Cenário"},{"body":"Uma boa revisão verifica se o problema foi entendido, se a solução é proporcional, se há testes relevantes, se autorização e dados estão seguros e se rollback/observabilidade foram considerados.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Leia o objetivo antes do diff.","Procure mudanças fora do escopo.","Cheque caminhos de erro e permissões.","Diferencie bloqueio obrigatório de preferência opcional."],"title":"Como aplicar"},{"body":"Num PR que adiciona exportação, a revisão deve verificar autorização do arquivo, limite de volume, tratamento de erro e ausência de dados sensíveis em logs, não apenas formatação.","type":"example","title":"Exemplo profissional"},{"body":"Aprovar porque 'os testes passaram' ignora riscos que a suíte ainda não cobre.","type":"mistake","title":"Erro comum"},{"body":"Crie um checklist de review para uma nova rota autenticada que altera dados.","type":"guided_practice","title":"Prática orientada"},{"body":"Review eficaz transfere conhecimento e melhora padrão coletivo sem transformar toda mudança em debate infinito.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Review é análise de risco.","Objetivo e escopo vêm antes do estilo.","Segurança e operação fazem parte da revisão.","Comentários devem ser acionáveis."]}],"lab_type":"checkpoint","position":5,"objective":"Revisar mudanças por risco, legibilidade, teste, segurança e impacto operacional.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":2,"options":["Não gostei.","Troque isso porque eu faria diferente.","Esta rota altera dados, mas não há verificação de autorização do recurso; adicione teste para usuário sem acesso.","Use outra cor."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual comentário de review é mais útil?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":8,"estimated_minutes":33},{"title":"Qualidade de release e regressão","content":[{"body":"Deploy bem-sucedido não significa release saudável. Uma aplicação pode subir e ainda perder login, checkout ou persistência.","type":"story","title":"Cenário"},{"body":"Release precisa de critérios pré e pós-deploy. Build/teste validam antes; smoke tests validam o ambiente real; métricas confirmam comportamento; rollback deve ser possível sem improviso.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Defina jornadas críticas de smoke test.","Cheque migrations e compatibilidade antes do deploy.","Observe erros e métricas logo após release.","Tenha critério objetivo para rollback."],"title":"Como aplicar"},{"body":"Após deploy de autenticação: health 200, login válido funciona, login inválido recusa, usuário A não acessa dados de B e taxa de erro não aumenta.","type":"example","title":"Exemplo profissional"},{"body":"Esperar reclamação de usuário como única validação pós-deploy aumenta tempo de detecção e impacto.","type":"mistake","title":"Erro comum"},{"body":"Escreva um checklist de release para uma alteração de schema com nova coluna obrigatória.","type":"guided_practice","title":"Prática orientada"},{"body":"Qualidade de release conecta engenharia e operação. O produto não termina quando o pipeline fica verde.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Release inclui pós-deploy.","Smoke test protege jornadas críticas.","Migrations exigem compatibilidade.","Rollback precisa de critério e caminho claro."]}],"lab_type":"checkpoint","position":6,"objective":"Construir uma barreira de release com testes, checklist, smoke test e critérios de rollback.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Uma pequena diferença de formatação sem impacto.","Aumento claro de erros no fluxo crítico logo após o deploy.","Um teste local antigo.","Um comentário no código."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual sinal justifica avaliar rollback imediatamente?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":8,"estimated_minutes":36},{"title":"Build, artefato e configuração de produção","content":[{"body":"Se cada ambiente compila de forma diferente e recebe arquivos manuais, não existe garantia de que o que foi testado é o que chegou à produção.","type":"story","title":"Cenário"},{"body":"O ideal é gerar um artefato imutável a partir de um commit e promover esse mesmo artefato entre ambientes. Configuração entra por variáveis e segredos gerenciados fora do repositório.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Associe build a commit/versionamento.","Não embuta segredos no bundle público.","Falhe cedo quando variável obrigatória estiver ausente.","Registre versão em health endpoint ou metadado equivalente."],"title":"Como aplicar"},{"body":"O pipeline cria build `abc123`, executa testes e publica. O health responde a mesma versão, permitindo relacionar incidente ao commit exato.","type":"example","title":"Exemplo profissional"},{"body":"Executar ajustes manuais no servidor depois do deploy cria estado impossível de reproduzir e auditar.","type":"mistake","title":"Erro comum"},{"body":"Liste quais informações de uma aplicação devem estar no código, em variável de ambiente e em secret manager.","type":"guided_practice","title":"Prática orientada"},{"body":"Artefato imutável melhora rollback, auditoria e investigação de incidentes.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Build precisa ser identificável.","Configuração não deve alterar o código-fonte.","Segredo não entra em bundle público.","Versão observável ajuda operação."]}],"lab_type":"checkpoint","position":1,"objective":"Separar build, artefato e configuração para produzir deploys reproduzíveis.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Editar arquivos manualmente em produção.","Gerar artefato versionado a partir de um commit e promover o mesmo artefato.","Copiar segredos para o repositório.","Compilar de forma diferente em cada servidor."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual prática torna um deploy mais reproduzível?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":9,"estimated_minutes":36},{"title":"CI/CD com gates de qualidade","content":[{"body":"Automação de deploy acelera tanto acertos quanto erros. O papel do pipeline é transformar critérios de qualidade em gates repetíveis.","type":"story","title":"Cenário"},{"body":"CI valida código; CD entrega mudanças de forma controlada. Gates podem incluir lint, testes, build, análise de dependência, migration checks e aprovação para ambientes sensíveis.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Falha em gate crítico deve impedir promoção.","Execute tarefas rápidas cedo para feedback curto.","Separe credenciais por ambiente.","Evite jobs com permissão maior que o necessário."],"title":"Como aplicar"},{"body":"PR executa lint, unitários e integração. Merge em main gera artefato e deploy de staging. Produção recebe o mesmo artefato após smoke e aprovação quando exigida.","type":"example","title":"Exemplo profissional"},{"body":"Guardar token de produção em variável exposta ao job de qualquer PR aumenta superfície de ataque, especialmente em código contribuído externamente.","type":"mistake","title":"Erro comum"},{"body":"Projete uma pipeline de quatro etapas para uma aplicação com banco e frontend.","type":"guided_practice","title":"Prática orientada"},{"body":"Pipeline é controle de mudança automatizado. Permissão, rastreabilidade e rollback são tão importantes quanto velocidade.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["CI valida; CD promove.","Gates codificam critérios de qualidade.","Credenciais precisam de menor privilégio.","O mesmo artefato deve ser promovido."]}],"lab_type":"checkpoint","position":2,"objective":"Desenhar pipeline que impeça mudanças inseguras de avançar sem validação adequada.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":0,"options":["Um teste crítico de autorização.","Uma mensagem informativa opcional.","Uma preferência de editor.","A ordem dos arquivos locais."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual gate deve bloquear um deploy quando falha?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":9,"estimated_minutes":39},{"title":"Migrations seguras e compatibilidade","content":[{"body":"Aplicação e banco não mudam exatamente no mesmo instante. Uma migration destrutiva pode quebrar instâncias antigas ainda atendendo requisições.","type":"story","title":"Cenário"},{"body":"Estratégia expand-and-contract cria primeiro estruturas compatíveis, adapta aplicação, migra dados e só depois remove o legado. Mudanças destrutivas exigem janela e plano de reversão ou roll-forward.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Adicione coluna antes de torná-la obrigatória quando houver dados existentes.","Faça backfill de forma controlada.","Mantenha leitura compatível durante transição.","Remova coluna antiga apenas após nenhum consumidor depender dela."],"title":"Como aplicar"},{"body":"Para renomear `name` para `full_name`: adicionar nova coluna, escrever nos dois campos temporariamente, backfill, migrar leitores, parar escrita antiga e só então remover `name`.","type":"example","title":"Exemplo profissional"},{"body":"Renomear ou remover coluna usada por uma versão ainda ativa causa erro imediato apesar de a migration ter 'funcionado'.","type":"mistake","title":"Erro comum"},{"body":"Desenhe uma migração segura para transformar `status` livre em um conjunto controlado de valores.","type":"guided_practice","title":"Prática orientada"},{"body":"Migrations são mudanças de produção com risco de dados. Precisam de métricas, backups adequados e compatibilidade.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Schema e aplicação coexistem durante deploy.","Expansão vem antes da contração.","Backfill deve ser controlado.","Mudança destrutiva exige plano."]}],"lab_type":"checkpoint","position":3,"objective":"Planejar mudanças de schema com expansão, migração de dados e contração sem quebrar versões em execução.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Remover antiga → adicionar nova → migrar código.","Adicionar nova → manter compatibilidade → migrar dados/leitores → remover antiga.","Apagar dados → criar backup depois.","Trocar tudo numa única alteração irreversível."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual ordem reduz risco ao substituir uma coluna em produção?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":9,"estimated_minutes":30},{"title":"Observabilidade: logs, métricas e traces","content":[{"body":"Uma aplicação pode responder 200 e ainda falhar para o negócio. Observabilidade precisa mostrar não apenas infraestrutura, mas também comportamento das jornadas importantes.","type":"story","title":"Cenário"},{"body":"Logs descrevem eventos discretos; métricas mostram tendências; traces conectam etapas de uma requisição. Bons sinais usam identificadores de correlação e evitam segredos ou dados pessoais desnecessários.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Logue evento e contexto técnico mínimo.","Use métricas de taxa, erro e latência.","Associe request/correlation id entre serviços.","Defina alertas sobre sintomas relevantes, não ruído."],"title":"Como aplicar"},{"body":"No checkout, métrica acompanha taxa de aprovação; logs registram `order_id` e categoria de erro; trace mostra tempo entre API, gateway e banco sem registrar cartão ou token.","type":"example","title":"Exemplo profissional"},{"body":"Logar payload completo por conveniência pode transformar observabilidade em repositório de dados sensíveis.","type":"mistake","title":"Erro comum"},{"body":"Defina três métricas e três campos de log para uma API de login sem registrar senha, token ou conteúdo pessoal desnecessário.","type":"guided_practice","title":"Prática orientada"},{"body":"Observabilidade reduz MTTR quando responde 'o que quebrou, para quem, desde quando e onde' rapidamente.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Logs, métricas e traces têm funções diferentes.","Correlação conecta eventos.","Sinais devem refletir jornada de negócio.","Segredos não pertencem a logs."]}],"lab_type":"checkpoint","position":4,"objective":"Criar sinais operacionais que permitam detectar, explicar e priorizar problemas sem expor dados sensíveis.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":2,"options":["request_id","categoria do erro","senha digitada","latência da operação"],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual informação é inadequada em um log de autenticação?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":9,"estimated_minutes":33},{"title":"Health checks, SLOs e alertas","content":[{"body":"Um endpoint responder 200 não prova que login, banco ou pagamento funcionam. Saúde precisa ser definida em níveis e ligada ao que o usuário percebe.","type":"story","title":"Cenário"},{"body":"Health check básico confirma processo; readiness confirma dependências necessárias; SLI mede comportamento; SLO define objetivo. Alertas devem indicar risco ao SLO ou falha real, não cada oscilação.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Separe liveness de readiness quando aplicável.","Escolha SLI alinhado ao fluxo de usuário.","Evite alertar sobre métricas sem ação possível.","Teste seus alertas e runbooks."],"title":"Como aplicar"},{"body":"Para API: SLI de disponibilidade = requisições válidas com resultado esperado / total; SLO 99,9%. Um alerta considera erro sustentado e impacto, não um único 500.","type":"example","title":"Exemplo profissional"},{"body":"Alertar a cada erro individual gera fadiga e faz a equipe ignorar sinais importantes.","type":"mistake","title":"Erro comum"},{"body":"Defina um SLI e um alerta para uma plataforma de aulas em que login e abertura de aula são jornadas críticas.","type":"guided_practice","title":"Prática orientada"},{"body":"SLO ajuda a negociar confiabilidade com velocidade de mudança usando evidência e risco.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Health não é igual a experiência completa.","SLI mede; SLO define objetivo.","Alerta precisa ser acionável.","Fadiga de alerta reduz segurança operacional."]}],"lab_type":"checkpoint","position":5,"objective":"Definir saúde técnica e objetivo de serviço com indicadores que evitem alertas inúteis.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Dispara para qualquer variação mínima.","Indica uma condição acionável com impacto ou risco relevante.","Não possui runbook.","Depende de alguém observar manualmente o dashboard."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"O que caracteriza um alerta útil?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":9,"estimated_minutes":36},{"title":"Rollback, feature flags e resposta a incidentes","content":[{"body":"Toda mudança carrega risco. O sistema fica mais resiliente quando a equipe consegue limitar o impacto sem precisar inventar uma solução durante o incidente.","type":"story","title":"Cenário"},{"body":"Rollback volta para versão conhecida; feature flag desativa comportamento sem novo deploy; resposta a incidentes prioriza estabilizar, comunicar, investigar e prevenir recorrência.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Escolha rollback quando versão anterior continua compatível.","Use flag para features isoláveis, não como substituto de arquitetura.","Registre horário, impacto e decisões do incidente.","Faça pós-incidente focado em sistema, não culpa."],"title":"Como aplicar"},{"body":"Nova recomendação causa erro em 15% das sessões. A flag desativa o recurso, métricas normalizam, depois a equipe investiga e adiciona teste de regressão.","type":"example","title":"Exemplo profissional"},{"body":"Tentar corrigir diretamente em produção sem reduzir impacto primeiro pode ampliar o incidente.","type":"mistake","title":"Erro comum"},{"body":"Escreva um runbook curto para aumento repentino de 500 após release.","type":"guided_practice","title":"Prática orientada"},{"body":"Maturidade operacional aparece na velocidade de estabilização e na qualidade das melhorias depois do incidente.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Primeiro reduza impacto.","Rollback exige compatibilidade.","Flags podem limitar raio de falha.","Incidente deve gerar prevenção."]}],"lab_type":"checkpoint","position":6,"objective":"Reduzir impacto de falhas com rollback, desligamento seletivo e resposta operacional estruturada.","xp_reward":150,"difficulty":5,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Descobrir quem errou.","Reduzir ou estabilizar o impacto antes da investigação completa.","Reescrever o sistema.","Esperar mais usuários reclamarem."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual é a prioridade inicial durante um incidente ativo com impacto crescente?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":9,"estimated_minutes":39},{"title":"Escolha do problema e escopo do projeto final","content":[{"body":"Projetos de portfólio falham quando tentam parecer grandes em vez de provar competência. Um produto pequeno, completo e bem documentado comunica mais do que dez telas incompletas.","type":"story","title":"Cenário"},{"body":"Escopo profissional começa por usuário, problema, jornada principal, dados e critérios de sucesso. O projeto final deve demonstrar integração, segurança, testes e deploy, não quantidade de features.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Escolha um usuário específico.","Defina uma jornada principal do início ao fim.","Liste explicitamente o que fica fora do escopo.","Crie critérios de aceite antes de desenvolver."],"title":"Como aplicar"},{"body":"Em vez de 'sistema de gestão completo', escolha 'agenda de serviços para profissional autônomo': cliente cria agendamento; profissional confirma; ambos visualizam estado; autorização isola dados.","type":"example","title":"Exemplo profissional"},{"body":"Adicionar chat, IA, marketplace e financeiro antes do CRUD principal estar sólido aumenta superfície sem aumentar evidência de domínio.","type":"mistake","title":"Erro comum"},{"body":"Escreva problema, usuário, fluxo principal, cinco critérios e três itens fora de escopo para seu projeto.","type":"guided_practice","title":"Prática orientada"},{"body":"Portfólio forte demonstra decisões e acabamento. Recrutador ou cliente precisa conseguir entender e testar rapidamente.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Escopo pequeno pode ser profissional.","Fluxo principal precisa estar completo.","Fora de escopo protege qualidade.","Critério de aceite orienta entrega."]}],"lab_type":"checkpoint","position":1,"objective":"Definir um problema realista, usuário, fluxo principal e escopo que possa ser entregue com qualidade.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Dez telas estáticas sem dados.","Um fluxo menor, completo, seguro, testado e publicado.","Um repositório sem README.","Uma lista de tecnologias sem aplicação."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual projeto tende a demonstrar melhor competência?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":10,"estimated_minutes":39},{"title":"Arquitetura do projeto final","content":[{"body":"Arquitetura não é um diagrama decorativo. Ela torna explícitas dependências, dados sensíveis e pontos de falha antes de eles virarem código.","type":"story","title":"Cenário"},{"body":"O projeto deve mostrar componentes principais, fluxo de dados e fronteiras de confiança. Cada regra crítica precisa ter um dono: UI, API, banco ou serviço externo.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Desenhe fluxo de autenticação e autorização.","Mapeie entidades e relacionamentos.","Identifique chamadas externas e falhas possíveis.","Defina onde cada validação obrigatória acontece."],"title":"Como aplicar"},{"body":"Num sistema de chamados, UI envia dados; API valida e autoriza; banco garante ownership e status; storage guarda anexo; webhook notifica. Cada elemento tem limite claro.","type":"example","title":"Exemplo profissional"},{"body":"Colocar a regra de autorização apenas na interface deixa a arquitetura vulnerável, mesmo que o diagrama pareça organizado.","type":"mistake","title":"Erro comum"},{"body":"Crie um diagrama textual de seu projeto usando caixas e setas e marque fronteiras de confiança.","type":"guided_practice","title":"Prática orientada"},{"body":"Uma arquitetura simples e explicável comunica maturidade melhor que uma coleção de serviços sem necessidade.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Arquitetura explicita responsabilidades.","Fronteira de confiança precisa de controle.","Cada regra deve ter uma camada responsável.","Simplicidade é qualidade quando atende o risco."]}],"lab_type":"checkpoint","position":2,"objective":"Desenhar fronteiras de frontend, API, banco, autenticação e integrações antes de implementar.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Apenas no botão da interface.","Na camada de autorização controlada pelo servidor/banco.","Somente no README.","No CSS."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Onde deve estar a regra que impede usuário A de editar recurso de B?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":10,"estimated_minutes":30},{"title":"Plano de implementação por fatias verticais","content":[{"body":"Construir primeiro todo o frontend e depois todo o backend posterga o maior risco: descobrir se as partes realmente se integram.","type":"story","title":"Cenário"},{"body":"Fatia vertical entrega um comportamento de ponta a ponta pequeno. Cada fatia inclui UI mínima, regra, API, banco e teste necessários. Isso cria feedback cedo e reduz integrações gigantes no fim.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Comece pela jornada de maior valor ou risco.","Mantenha cada fatia demonstrável.","Integre cedo com dados reais de teste.","Evite abstrações para features ainda inexistentes."],"title":"Como aplicar"},{"body":"Fatia 1: criar tarefa e listar. Fatia 2: editar com autorização. Fatia 3: anexar arquivo. Cada etapa já funciona ponta a ponta.","type":"example","title":"Exemplo profissional"},{"body":"Criar dez componentes genéricos antes de existir uso real pode produzir abstrações caras e erradas.","type":"mistake","title":"Erro comum"},{"body":"Quebre seu projeto final em quatro fatias verticais e defina o critério de pronto de cada uma.","type":"guided_practice","title":"Prática orientada"},{"body":"Fatiamento vertical melhora previsão e torna portfólio demonstrável desde cedo.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Integração deve acontecer cedo.","Fatia vertical atravessa camadas.","Cada incremento precisa ser demonstrável.","Abstração vem após padrão real."]}],"lab_type":"checkpoint","position":3,"objective":"Entregar o projeto em incrementos demonstráveis que atravessam interface, regra, persistência e teste.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Criar todos os componentes visuais sem API.","Implementar 'criar tarefa' da UI ao banco com teste.","Modelar todas as tabelas sem fluxo.","Escrever apenas documentação."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual exemplo é uma fatia vertical?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":10,"estimated_minutes":33},{"title":"README, documentação e evidências","content":[{"body":"Um bom projeto pode parecer fraco se ninguém consegue executá-lo. README é parte da experiência do avaliador e da própria operação do software.","type":"story","title":"Cenário"},{"body":"Documentação mínima cobre problema, solução, arquitetura, stack, setup, variáveis, scripts, testes, decisão técnica, limitações e link publicado. Evidências concretas são melhores que adjetivos.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Inclua instruções reproduzíveis.","Mostre arquitetura de forma simples.","Documente decisões e trade-offs reais.","Liste limitações conhecidas sem esconder problemas."],"title":"Como aplicar"},{"body":"Em vez de 'aplicação escalável e robusta', explique: 'RLS isola recursos por user_id; índice em owner_id cobre consulta principal; uploads limitados a X MB'.","type":"example","title":"Exemplo profissional"},{"body":"README cheio de badges e sem instrução de execução adiciona aparência, não reprodutibilidade.","type":"mistake","title":"Erro comum"},{"body":"Esboce as seções do README do seu projeto e escreva uma decisão técnica com alternativa descartada.","type":"guided_practice","title":"Prática orientada"},{"body":"Documentação demonstra comunicação técnica e reduz custo de avaliação, onboarding e manutenção.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["README deve permitir reprodução.","Decisão precisa de contexto e trade-off.","Evidência vence adjetivo.","Limitações comunicadas aumentam credibilidade."]}],"lab_type":"checkpoint","position":4,"objective":"Documentar projeto para que outra pessoa entenda objetivo, execute, teste e avalie decisões.","xp_reward":150,"difficulty":4,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["O projeto é muito seguro.","Usei RLS para restringir cada linha ao proprietário porque a aplicação é multiusuário.","A arquitetura é moderna.","O código é limpo."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual frase demonstra melhor uma decisão técnica?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":10,"estimated_minutes":36},{"title":"Apresentação técnica e demonstração","content":[{"body":"Demonstração eficiente começa pelo problema e prova o fluxo real. Navegar aleatoriamente pela interface torna difícil perceber competência técnica.","type":"story","title":"Cenário"},{"body":"Uma boa demo mostra: contexto, jornada principal, caso de erro/segurança, teste ou observabilidade e arquitetura. O objetivo é evidenciar comportamento, não mostrar cada arquivo.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Tenha dados de demonstração controlados.","Mostre um caminho feliz e um caso de proteção.","Evite depender de serviços instáveis sem fallback.","Prepare link e repositório acessíveis."],"title":"Como aplicar"},{"body":"Em 5 minutos: login A → cria recurso → login B não acessa → teste automatizado protege regra → diagrama mostra onde autorização ocorre.","type":"example","title":"Exemplo profissional"},{"body":"Passar a maior parte da apresentação lendo código linha por linha esconde o valor do sistema e consome tempo.","type":"mistake","title":"Erro comum"},{"body":"Escreva um roteiro de demo de cinco etapas para seu projeto final.","type":"guided_practice","title":"Prática orientada"},{"body":"Apresentação técnica é síntese: produto, engenharia e comunicação precisam aparecer juntos.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Demo prova comportamento.","Mostre segurança/erro, não só sucesso.","Roteiro reduz improviso.","Código é evidência, não necessariamente o centro da apresentação."]}],"lab_type":"checkpoint","position":5,"objective":"Preparar uma demonstração curta que prove funcionamento, qualidade e decisões sem depender de discurso promocional.","xp_reward":150,"difficulty":5,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Listar todas as bibliotecas.","Mostrar um fluxo real e um caso de autorização/erro funcionando.","Usar muitas animações.","Esconder limitações."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Qual elemento aumenta mais a força de uma demonstração técnica?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":10,"estimated_minutes":39},{"title":"Checklist final de portfólio e entrega","content":[{"body":"A última etapa não é adicionar feature; é reduzir defeitos e remover atritos para quem vai avaliar o trabalho.","type":"story","title":"Cenário"},{"body":"Checklist final cobre comportamento, segurança, testes, dados, responsividade, acessibilidade, deploy, observabilidade, documentação e limpeza do repositório. Tudo que não pode ser demonstrado deve ser tratado como não comprovado.","type":"concept","title":"Princípio central"},{"type":"mechanics","items":["Teste do zero em conta/navegador limpo.","Revogue ou troque credenciais expostas.","Confirme que README reproduz o projeto.","Faça smoke test da URL pública e links."],"title":"Como aplicar"},{"body":"Antes de enviar: clonar em pasta limpa, configurar pelo `.env.example`, rodar testes, executar app, criar duas contas, validar isolamento e abrir a URL pública em mobile.","type":"example","title":"Exemplo profissional"},{"body":"Entregar com segredo no histórico Git é problema mesmo que ele tenha sido removido do arquivo atual. Credencial precisa ser revogada e o histórico tratado adequadamente.","type":"mistake","title":"Erro comum"},{"body":"Monte uma checklist de 12 itens e execute-a sobre seu projeto antes de considerar concluído.","type":"guided_practice","title":"Prática orientada"},{"body":"Polimento final comunica responsabilidade. Portfólio profissional é um artefato verificável, não apenas uma ideia implementada parcialmente.","type":"professional_context","title":"No trabalho real"},{"type":"recap","items":["Auditoria final reduz atrito e risco.","Teste instalação limpa.","Segredo exposto precisa ser revogado.","Entrega só está pronta quando pode ser reproduzida e avaliada."]}],"lab_type":"checkpoint","position":6,"objective":"Auditar funcionalidade, segurança, qualidade, publicação e documentação antes da submissão final.","xp_reward":150,"difficulty":5,"lab_config":{"pedagogy":"contexto-conceito-exemplo-pratica-validacao","checkpoint":{"answer":1,"options":["Nenhuma.","Revogar/rotacionar o token e tratar o histórico conforme necessário.","Renomear o arquivo.","Adicionar um comentário."],"feedback":"Correto. A decisão preserva o critério técnico da aula.","question":"Se um token real foi commitado e depois removido do arquivo, qual ação continua necessária?","feedback_incorrect":"Revise o princípio central e escolha a alternativa que reduz risco de forma verificável."},"editorial_version":"lc-pro-fullstack-1.0"},"lesson_type":"micro","module_position":10,"estimated_minutes":30}]$lessons$::jsonb)
 as x(module_position int,position int,title text,objective text,estimated_minutes int,content jsonb,lesson_type text,lab_type text,lab_config jsonb,xp_reward int,difficulty int)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.lessons(module_id,title,objective,estimated_minutes,content,position,status,lesson_type,lab_type,lab_config,xp_reward,difficulty)
select m.id,p.title,p.objective,p.estimated_minutes,p.content,p.position,'draft',p.lesson_type,p.lab_type,p.lab_config,p.xp_reward,p.difficulty
from payload p,c join nexora.modules m on m.course_id=c.id and m.position=p.module_position
on conflict(module_id,position) do update set
 title=excluded.title,objective=excluded.objective,estimated_minutes=excluded.estimated_minutes,content=excluded.content,
 lesson_type=excluded.lesson_type,lab_type=excluded.lab_type,lab_config=excluded.lab_config,xp_reward=excluded.xp_reward,
 difficulty=excluded.difficulty,updated_at=now();

with payload as (
 select * from jsonb_to_recordset($assessments$[{"title":"LC Pro Full Stack — M8 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":8,"randomize_questions":true},{"title":"LC Pro Full Stack — M9 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":9,"randomize_questions":true},{"title":"LC Pro Full Stack — M10 • Checkpoint","pass_score":70,"max_attempts":3,"module_position":10,"randomize_questions":true}]$assessments$::jsonb)
 as x(module_position int,title text,pass_score numeric,max_attempts int,randomize_questions boolean)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.assessments(course_id,module_id,title,pass_score,max_attempts,randomize_questions,status)
select c.id,m.id,p.title,p.pass_score,p.max_attempts,p.randomize_questions,'draft'
from payload p,c join nexora.modules m on m.course_id=c.id and m.position=p.module_position
where not exists(select 1 from nexora.assessments a where a.course_id=c.id and a.module_id=m.id and a.title=p.title);

with payload as (
 select * from jsonb_to_recordset($module_questions$[{"prompt":"Qual decisão representa melhor uma estratégia de testes saudável?","options":[{"id":"c","label":"Evitar testes de integração."},{"id":"d","label":"Medir qualidade apenas por quantidade de testes."},{"id":"a","label":"Testar tudo apenas com E2E."},{"id":"b","label":"Usar o nível de teste mais barato que detecta o risco e reservar E2E para jornadas críticas."}],"position":1,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":8,"assessment_title":"LC Pro Full Stack — M8 • Checkpoint","feedback_correct":"Correto. Tipos de teste protegem riscos diferentes.","feedback_incorrect":"Revise a aula e identifique a opção que corresponde ao comportamento verificável."},{"prompt":"Qual trio valida melhor uma regra 'idade mínima de 18 anos'?","options":[{"id":"b","label":"17, 18 e 19"},{"id":"c","label":"18, 28 e 38"},{"id":"d","label":"0, 50 e 100"},{"id":"a","label":"1, 2 e 3"}],"position":2,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":8,"assessment_title":"LC Pro Full Stack — M8 • Checkpoint","feedback_correct":"Correto. Fronteiras derivam da regra.","feedback_incorrect":"Revise a aula e identifique a opção que corresponde ao comportamento verificável."},{"prompt":"Quando um teste com banco real de teste é mais valioso que um mock?","options":[{"id":"a","label":"Quando queremos testar CSS."},{"id":"b","label":"Quando o risco está em constraints, transações ou SQL real."},{"id":"c","label":"Quando não existe regra de persistência."},{"id":"d","label":"Quando queremos evitar qualquer infraestrutura."}],"position":3,"difficulty":3,"question_type":"multiple_choice","correct_answer":{"option_id":"b"},"module_position":8,"assessment_title":"LC Pro Full Stack — M8 • Checkpoint","feedback_correct":"Correto. Integração valida colaboração real.","feedback_incorrect":"Revise a aula e identifique a opção que corresponde a