reduz dependência de afirmações."}]$module_questions$::jsonb)
 as x(module_position int,assessment_title text,position int,prompt text,question_type text,options jsonb,correct_answer jsonb,feedback_correct text,feedback_incorrect text,difficulty int)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position)
select a.id,p.prompt,p.question_type,p.options,p.correct_answer,p.feedback_correct,p.feedback_incorrect,p.difficulty,p.position
from payload p,c
join nexora.modules m on m.course_id=c.id and m.position=p.module_position
join nexora.assessments a on a.course_id=c.id and a.module_id=m.id and a.title=p.assessment_title
where not exists(select 1 from nexora.questions q where q.assessment_id=a.id and q.position=p.position);

with cfg as (
 select * from jsonb_to_record($final_assessment${"title":"LC Pro Full Stack — Avaliação Final","pass_score":70,"max_attempts":3,"randomize_questions":true}$final_assessment$::jsonb)
 as x(title text,pass_score numeric,max_attempts int,randomize_questions boolean)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.assessments(course_id,module_id,title,pass_score,max_attempts,randomize_questions,status)
select c.id,null,cfg.title,cfg.pass_score,cfg.max_attempts,cfg.randomize_questions,'draft'
from c,cfg
where not exists(select 1 from nexora.assessments a where a.course_id=c.id and a.module_id is null and a.title=cfg.title);

