with payload as (
 select * from jsonb_to_recordset($projects$[{"title":"Boss Fight — Especificação e arquitetura verificável","rubric":{"version":"lc-pro-fullstack-1.0","criteria":[{"name":"Critérios de aceite verificáveis","weight":25},{"name":"Arquitetura e fronteiras de confiança","weight":25},{"name":"Reprodutibilidade do ambiente","weight":20},{"name":"Histórico Git e documentação","weight":20},{"name":"Evidências de validação","weight":10}],"deliverables":["Artefato técnico demonstrável","README com instruções de reprodução","Evidências de teste/validação","Decisões e limitações conhecidas"],"minimum_score":70,"review_guidance":{"approved":"Aprovar apenas quando a entrega for reproduzível, demonstrar a competência do módulo e atingir nota final mínima de 70.","revision_requested":"Indicar o critério não demonstrado, a evidência ausente e uma ação verificável para a nova submissão."},"required_evidence":["fluxo principal demonstrável","ao menos um cenário de erro ou fronteira","instruções suficientes para reprodução","decisão técnica principal justificada"]},"xp_reward":500,"description":"Entregue um repositório com escopo, critérios de aceite, fluxo Web ponta a ponta, variáveis de ambiente documentadas e histórico Git coerente. A entrega deve provar que outra pessoa consegue entender o problema, executar o projeto-base e identificar onde ficam validação, autorização e persistência.","project_kind":"boss_fight","module_position":1},{"title":"Boss Fight — Interface profissional responsiva","rubric":{"version":"lc-pro-fullstack-1.0","criteria":[{"name":"Semântica e acessibilidade","weight":25},{"name":"Responsividade e composição","weight":25},{"name":"Formulários e estados","weight":20},{"name":"Performance percebida","weight":15},{"name":"Publicação e documentação","weight":15}],"deliverables":["Artefato técnico demonstrável","README com instruções de reprodução","Evidências de teste/validação","Decisões e limitações conhecidas"],"minimum_score":70,"review_guidance":{"approved":"Aprovar apenas quando a entrega for reproduzível, demonstrar a competência do módulo e atingir nota final mínima de 70.","revision_requested":"Indicar o critério não demonstrado, a evidência ausente e uma ação verificável para a nova submissão."},"required_evidence":["fluxo principal demonstrável","ao menos um cenário de erro ou fronteira","instruções suficientes para reprodução","decisão técnica principal justificada"]},"xp_reward":550,"description":"Construa e publique uma interface semântica, responsiva e acessível com formulário completo, estados de loading/erro/sucesso e performance básica validada. A entrega precisa funcionar por teclado e em viewport móvel.","project_kind":"boss_fight","module_position":2},{"title":"Boss Fight — Aplicação React tipada","rubric":{"version":"lc-pro-fullstack-1.0","criteria":[{"name":"Modelagem de estado","weight":25},{"name":"TypeScript e contratos","weight":20},{"name":"Fluxo assíncrono e erros","weight":20},{"name":"Componentização e clareza","weight":20},{"name":"Testes e documentação","weight":15}],"deliverables":["Artefato técnico demonstrável","README com instruções de reprodução","Evidências de teste/validação","Decisões e limitações conhecidas"],"minimum_score":70,"review_guidance":{"approved":"Aprovar apenas quando a entrega for reproduzível, demonstrar a competência do módulo e atingir nota final mínima de 70.","revision_requested":"Indicar o critério não demonstrado, a evidência ausente e uma ação verificável para a nova submissão."},"required_evidence":["fluxo principal demonstrável","ao menos um cenário de erro ou fronteira","instruções suficientes para reprodução","decisão técnica principal justificada"]},"xp_reward":600,"description":"Entregue uma SPA em React + TypeScript com estado explícito, filtros, formulário, consumo de API, estados assíncronos e tratamento de erro. Evite estado duplicado e any desnecessário.","project_kind":"boss_fight","module_position":3},{"title":"Boss Fight — API REST com regras de n