eliverables":["Artefato técnico demonstrável","README com instruções de reprodução","Evidências de teste/validação","Decisões e limitações conhecidas"],"minimum_score":70,"review_guidance":{"approved":"Aprovar apenas quando a entrega for reproduzível, demonstrar a competência do módulo e atingir nota final mínima de 70.","revision_requested":"Indicar o critério não demonstrado, a evidência ausente e uma ação verificável para a nova submissão."},"required_evidence":["fluxo principal demonstrável","ao menos um cenário de erro ou fronteira","instruções suficientes para reprodução","decisão técnica principal justificada"]},"xp_reward":750,"description":"Integre frontend, API, banco e autenticação em um fluxo completo. A aplicação deve tratar loading, erro, vazio, autorização e persistência, com ao menos uma jornada principal publicada em ambiente de teste.","project_kind":"boss_fight","module_position":7},{"title":"Boss Fight — Quality Gate e regressão","rubric":{"version":"lc-pro-fullstack-1.0","criteria":[{"name":"Cobertura de riscos","weight":25},{"name":"Casos de fronteira","weight":20},{"name":"Integração/E2E crítico","weight":20},{"name":"Regressão e depuração","weight":20},{"name":"Quality gate documentado","weight":15}],"deliverables":["Artefato técnico demonstrável","README com instruções de reprodução","Evidências de teste/validação","Decisões e limitações conhecidas"],"minimum_score":70,"review_guidance":{"approved":"Aprovar apenas quando a entrega for reproduzível, demonstrar a competência do módulo e atingir nota final mínima de 70.","revision_requested":"Indicar o critério não demonstrado, a evidência ausente e uma ação verificável para a nova submissão."},"required_evidence":["fluxo principal demonstrável","ao menos um cenário de erro ou fronteira","instruções suficientes para reprodução","decisão técnica principal justificada"]},"xp_reward":700,"description":"Adicione estratégia de testes ao projeto integrado: unitários de fronteira, integração, um fluxo E2E crítico, checklist de code review e teste de regressão para um bug reproduzido.","project_kind":"boss_fight","module_position":8},{"title":"Boss Fight — Deploy observável e reversível","rubric":{"version":"lc-pro-fullstack-1.0","criteria":[{"name":"Pipeline e artefato rastreável","weight":25},{"name":"Configuração e segredos","weight":20},{"name":"Observabilidade","weight":20},{"name":"Smoke/health e SLO básico","weight":15},{"name":"Rollback e runbook","weight":20}],"deliverables":["Artefato técnico demonstrável","README com instruções de reprodução","Evidências de teste/validação","Decisões e limitações conhecidas"],"minimum_score":70,"review_guidance":{"approved":"Aprovar apenas quando a entrega for reproduzível, demonstrar a competência do módulo e atingir nota final mínima de 70.","revision_requested":"Indicar o critério não demonstrado, a evidência ausente e uma ação verificável para a nova submissão."},"required_evidence":["fluxo principal demonstrável","ao menos um cenário de erro ou fronteira","instruções suficientes para reprodução","decisão técnica principal justificada"]},"xp_reward":750,"description":"Publique a aplicação com pipeline, configuração por ambiente, health/versionamento, logs seguros e smoke tests. Documente rollback e resposta a um cenário de incidente simulado.","project_kind":"boss_fight","module_position":9},{"title":"Boss Fight Final — Produto Full Stack de portfólio","rubric":{"version":"lc-pro-fullstack-1.0","criteria":[{"name":"Produto e fluxo principal","weight":20},{"name":"Arquitetura e integração","weight":20},{"name":"Segurança e dados","weight":20},{"name":"Testes e qualidade","weight":15},{"name":"Deploy e observabilidade","weight":10},{"name":"README, portfólio e demonstração","weight":15}],"deliverables":["Artefato técnico demonstrável","README com instruções de reprodução","Evidências de teste/validação","Decisões e limitações conhecidas"],"minimum_score":70,"review_guidance":{"approved":"Aprovar apenas quando a entrega for reproduzível, demonstrar a competência do módulo e atingir nota final mínima de 70.","revision_requested":"Indicar o critério não demonstrado, a evidência ausente e uma ação verificável para a nova submissão."},"required_evidence":["fluxo principal demonstrável","ao menos um cenário de erro ou fronteira","instruções suficientes para reprodução","decisão técnica principal justificada"]},"xp_reward":1200,"description":"Entregue um produto Full Stack completo, publicado, testado e documentado. Deve existir usuário/problema claro, fluxo principal ponta a ponta, autenticação/autorização, banco com integridade, testes, observabilidade mínima, README reproduzível e demonstração técnica.","project_kind":"boss_fight","module_position":10}]$projects$::jsonb)
 as x(module_position int,title text,description text,rubric jsonb,project_kind text,xp_reward int)
), c as (select id from nexora.courses where slug='lc-pro-programador-full-stack')
insert into nexora.projects(course_id,module_id,title,description,rubric,status,project_kind,xp_reward)
select c.id,m.id,p.title,p.description,p.rubric,'draft',p.project_kind,p.xp_reward
from payload p,c join nexora.modules m on m.course_id=c.id and m.position=p.module_position
where not exists(select 1 from nexora.projects pr where pr.course_id=c.id and pr.module_id=m.id and pr.title=p.title);

do $$
declare
  v_course uuid;
  v_modules int; v_lessons int; v_assessments int; v_module_assessments int;
  v_final_assessments int; v_questions int; v_projects int; v_bad_questions int; v_bad_projects int;
begin
  select id into v_course from nexora.courses where slug='lc-pro-programador-full-stack' and access_tier='pro';
  if v_course is null then raise exception 'lc_pro_course_missing'; end if;

  select count(*) into v_modules from nexora.modules where course_id=v_course;
  select count(*) into v_lessons from nexora.lessons l join nexora.modules m on m.id=l.module_id where m.course_id=v_course;
  select count(*),count(*) filter(where module_id is not null),count(*) filter(where module_id is null)
    into v_assessments,v_module_assessments,v_final_assessments from nexora.assessments where course_id=v_course;
  select count(*) into v_questions from nexora.questions q join nexora.assessments a on a.id=q.assessment_id where a.course_id=v_course;
  select count(*) into v_projects from nexora.projects where course_id=v_course;

  select count(*) into v_bad_questions
  from nexora.questions q join nexora.assessments a on a.id=q.assessment_id
  where a.course_id=v_course and (
    jsonb_typeof(q.options)<>'array' or jsonb_array_length(q.options)<>4
    or coalesce(q.correct_answer->>'option_id',q.correct_answer->>'id','')=''
    or not exists(select 1 from jsonb_array_elements(q.options) o where o->>'id'=coalesce(q.correct_answer->>'option_id',q.correct_answer->>'id'))
    or coalesce(length(trim(q.feedback_correct)),0)<12 or coalesce(length(trim(q.feedback_incorrect)),0)<12
  );

  select count(*) into v_bad_projects
  from nexora.projects p where p.course_id=v_course and (
    coalesce((select sum((x->>'weight')::int) from jsonb_array_elements(p.rubric->'criteria') x),0)<>100
    or jsonb_array_length(coalesce(p.rubric->'criteria','[]'::jsonb))<4
    or jsonb_array_length(coalesce(p.rubric->'deliverables','[]'::jsonb))<3
    or coalesce((p.rubric->>'minimum_score')::numeric,0)<>70
  );

  if v_modules<>10 or v_lessons<>58 or v_assessments<>11 or v_module_assessments<>10
     or v_final_assessments<>1 or v_questions<>88 or v_projects<>10 or v_bad_questions<>0 or v_bad_projects<>0 then
    raise exception 'lc_pro_launch_gate_failed';
  end if;

  if not exists(
    select 1 from nexora.course_completion_rules r
    where r.course_id=v_course and r.minimum_lesson_progress=100 and r.minimum_assessment_score=70
      and r.require_all_module_assessments and r.require_final_assessment and r.require_final_project
      and r.minimum_project_score=70 and r.certificate_enabled
  ) then raise exception 'lc_pro_completion_rules_invalid'; end if;

  if not exists(
    select 1 from nexora.commerce_products p
    join nexora.commerce_product_courses pc on pc.product_id=p.id
    where p.slug='programador-full-stack-pro' and pc.course_id=v_course
      and p.current_price_cents=29700 and p.list_price_cents=49700 and p.affiliate_commission_bps=4000
  ) then raise exception 'lc_pro_product_configuration_invalid'; end if;

  update nexora.lessons l set status='published',updated_at=now()
  from nexora.modules m where l.module_id=m.id and m.course_id=v_course;
  update nexora.assessments set status='published' where course_id=v_course;
  update nexora.projects set status='published' where course_id=v_course;
  update nexora.courses set status='published',updated_at=now() where id=v_course;
  update nexora.commerce_products set sales_status='active',updated_at=now() where slug='programador-full-stack-pro';
end $$;
